// NewCveContentType create CveContentType
func NewCveContentType(name string) CveContentType {
	switch name {
	case "nvd":
		return Nvd
	case "jvn":
		return Jvn
	case "redhat", "centos", "alma", "rocky":
		return RedHat
	case "fedora":
		return Fedora
	case "oracle":
		return Oracle
	case "ubuntu":
		return Ubuntu
	case "debian", "debian-oval", "raspbian":
		return Debian
	case "redhat_api":
		return RedHatAPI
	case "debian_security_tracker":
		return DebianSecurityTracker
	case "ubuntu_api":
		return UbuntuAPI
	case constant.OpenSUSE, constant.OpenSUSELeap, constant.SUSEEnterpriseServer, constant.SUSEEnterpriseDesktop:
		return SUSE
	case "microsoft":
		return Microsoft
	case "wordpress":
		return WpScan
	case "amazon":
		return Amazon
	case "trivy":
		return Trivy
	case "GitHub":
		return Trivy
	default:
		return Unknown
	}
}

// GetCveContentTypes returns CVE content types associated with an OS family.
func GetCveContentTypes(family string) []CveContentType {
	switch family {
	case "redhat", "centos", "alma", "rocky":
		return []CveContentType{RedHat, RedHatAPI}
	case "debian", "debian-oval", "raspbian":
		return []CveContentType{Debian, DebianSecurityTracker}
	case "ubuntu":
		return []CveContentType{Ubuntu, UbuntuAPI}
	default:
		ctype := NewCveContentType(family)
		if ctype == Unknown {
			return nil
		}
		return []CveContentType{ctype}
	}
}

